import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"408 统考计算机网络 (Computer Network) —— 知识库总览","description":"","frontmatter":{},"headers":[],"relativePath":"计算机网络/index.md","filePath":"计算机网络/index.md","lastUpdated":1777091574000}'),l={name:"计算机网络/index.md"};function i(n,t,s,h,_,P){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_408-统考计算机网络-computer-network-——-知识库总览" tabindex="-1">408 统考计算机网络 (Computer Network) —— 知识库总览 <a class="header-anchor" href="#_408-统考计算机网络-computer-network-——-知识库总览" aria-label="Permalink to &quot;408 统考计算机网络 (Computer Network) —— 知识库总览&quot;">​</a></h1><blockquote><p>本资料库汇集了 408 考研《计算机网络》科目的全部核心知识点、重难点梳理及考频分析，涵盖体系结构、物理层、数据链路层、网络层、传输层和应用层六大板块。</p></blockquote><hr><h2 id="📂-理论模块" tabindex="-1">📂 理论模块 <a class="header-anchor" href="#📂-理论模块" aria-label="Permalink to &quot;📂 理论模块&quot;">​</a></h2><p>基于王道考研讲义与多源笔记深度融合，按 TCP/IP 五层模型编排：</p><ul><li><strong><a href="./01_计算机网络体系结构.html">01_计算机网络体系结构</a></strong>：网络概念/组成/功能/分类；OSI/TCP-IP/五层模型；性能指标（带宽/时延/吞吐量/RTT）。</li><li><strong><a href="./02_物理层.html">02_物理层</a></strong>：通信基础（信号/编码/调制）；奈奎斯特定理与香农定理；传输介质；物理层设备。</li><li><strong><a href="./03_数据链路层.html">03_数据链路层</a></strong>：封装成帧/透明传输/差错控制；流量控制（停等/GBN/SR）；介质访问控制（CSMA-CD/CSMA-CA）；局域网与以太网。</li><li><strong><a href="./04_网络层.html">04_网络层</a></strong>：IPv4 地址/子网划分/CIDR；ARP/DHCP/ICMP 协议；路由算法（RIP/OSPF/BGP）；IPv6 基础；路由器工作原理。</li><li><strong><a href="./05_传输层.html">05_传输层</a></strong>：UDP 协议；TCP 协议（连接管理/可靠传输/流量控制/拥塞控制）；端口号与复用分用。</li><li><strong><a href="./06_应用层.html">06_应用层</a></strong>：DNS；FTP；电子邮件（SMTP/POP3/IMAP）；HTTP/HTTPS；DHCP（应用层角度）。</li></ul><h2 id="🎯-提分与回顾" tabindex="-1">🎯 提分与回顾 <a class="header-anchor" href="#🎯-提分与回顾" aria-label="Permalink to &quot;🎯 提分与回顾&quot;">​</a></h2><ul><li><strong><a href="./07_考频与重难点总结.html">07_考频与重难点总结</a></strong>：包含计算机网络各章选择题高频考点、计算题套路（子网划分/时延计算/滑动窗口）及易错辨析。</li></ul><hr><h2 id="💡-备考建议" tabindex="-1">💡 备考建议 <a class="header-anchor" href="#💡-备考建议" aria-label="Permalink to &quot;💡 备考建议&quot;">​</a></h2><ol><li>计算机网络的核心在于【传输层 TCP】和【网络层 IP】，占整科分值约 50%。TCP 三次握手/四次挥手、滑动窗口/拥塞控制是历年大题重灾区。</li><li>数据链路层的流量控制与介质访问控制易出选择题和计算题，需要熟练掌握停等/GBN/SR 的窗口大小与效率计算。</li><li>子网划分与 CIDR 聚合是必考计算题，务必做到又快又准。应用层协议以选择题为主，注意各协议使用的端口号和传输层协议。</li></ol>',11)])])}const m=a(l,[["render",i]]);export{c as __pageData,m as default};
